                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.snitch_final_get_put_away_new AS SELECT _airbyte_data:\"EAN\"::STRING AS EAN ,_airbyte_data:\"Name\"::STRING AS NAME ,_airbyte_data:\"Type\"::STRING AS TYPE ,_airbyte_data:Created::TIMESTAMP AS CREATED ,_airbyte_data:Updated::TIMESTAMP AS UPDATED ,_airbyte_data:\"Category\"::STRING AS \"CATEGORY\" ,_airbyte_data:\"Batch Code\"::STRING AS \"Batch Code\" ,_airbyte_data:\"Created By\"::STRING AS \"Created By\" ,_airbyte_data:\"Shelf Code\"::STRING AS \"Shelf Code\" ,_airbyte_data:\"Putaway Code\"::STRING AS \"Putaway Code\" ,_airbyte_data:\"Inventory Type\"::STRING AS \"Inventory Type\" ,_airbyte_data:\"Total Quantity\"::INTEGER AS \"Total Quantity\" ,_airbyte_data:\"Warehouse Name\"::STRING AS \"Warehouse Name\" ,_airbyte_data:\"Putaway Item Id\"::STRING AS \"Putaway Item Id\" ,_airbyte_data:\"Item Type skuCode\"::STRING AS \"Item Type skuCode\" ,_airbyte_data:\"Putaway qc Comment\"::STRING AS \"Putaway qc Comment\" ,_airbyte_data:\"Putaway Status Code\"::STRING AS \"Putaway Status Code\" ,_airbyte_data:\"Bad inventory Reason\"::STRING AS \"Bad inventory Reason\" ,_airbyte_data:\"Putaway Item Status Code\"::STRING AS \"Putaway Item Status Code\" ,_airbyte_data:\"Putaway Completed Quantity\"::INTEGER AS \"Putaway Completed Quantity\" FROM snitch_db.maplemonk._airbyte_raw_snitch_final_get_put_away_new QUALIFY ROW_NUMBER() OVER (PARTITION BY \"Putaway Item Id\",\"Warehouse Name\",\"Putaway Code\",Created ORDER BY _airbyte_data:\"Updated\" DESC) = 1; CREATE OR REPLACE TABLE snitch_db.maplemonk.putaway_tracking AS WITH data AS ( SELECT a.\"Putaway Code\", CASE WHEN a.\"Warehouse Name\" = \'SAPL-WH1\' AND TRIM(a.\"Putaway Code\") IN ( \'PT54775\',\'PT54782\',\'PT54780\',\'PT54781\',\'PT54783\',\'PT54776\',\'PT54785\',\'PT57028\',\'PT51905\',\'PT56406\',\'PT55271\',\'PT55290\',\'PT55267\',\'PT55266\',\'PT55265\', \'PT55270\',\'PT55269\',\'PT55268\',\'PT55293\',\'PT55292\',\'PT55291\',\'PT55318\',\'PT55639\',\'PT56029\',\'PT56030\',\'PT56031\',\'PT56032\',\'PT56289\',\'PT56034\',\'PT56283\', \'PT56285\',\'PT56130\',\'PT56043\',\'PT55660\',\'PT56233\',\'PT56231\',\'PT56287\',\'PT56290\',\'PT55652\',\'PT56288\',\'PT56229\',\'PT56286\',\'PT56284\',\'PT56217\',\'PT55926\', \'PT50297\',\'PT55728\',\'PT55921\',\'PT56281\',\'PT56280\',\'PT55729\',\'PT55788\',\'PT47501\',\'PT56230\',\'PT56220\',\'PT56218\',\'PT56038\',\'PT56105\',\'PT56044\',\'PT56107\', \'PT56108\',\'PT56039\',\'PT56282\',\'PT56219\',\'PT56106\',\'PT58789\',\'PT56235\',\'PT56216\',\'PT57020\',\'PT56557\',\'PT57021\',\'PT57381\',\'PT57257\',\'PT56527\',\'PT57380\', \'PT57022\',\'PT56526\',\'PT57023\',\'PT56528\',\'PT56556\',\'PT57379\',\'PT57031\',\'PT56909\',\'PT57024\',\'PT57027\',\'PT56911\',\'PT56908\',\'PT56913\',\'PT56797\',\'PT56798\', \'PT56905\',\'PT56903\',\'PT57030\',\'PT56907\',\'PT56906\',\'PT57048\',\'PT56904\',\'PT56910\',\'PT57049\',\'PT57044\',\'PT57047\',\'PT57258\',\'PT57244\',\'PT57245\',\'PT50197\', \'PT57752\',\'PT58180\',\'PT58181\',\'PT58182\',\'PT58183\',\'PT58184\',\'PT58185\',\'PT58187\',\'PT58189\',\'PT57750\',\'PT58186\' ) THEN \'B2B MP Returns\' WHEN \"Warehouse Name\" LIKE \'%TAURU%\' AND \"Putaway Code\" IN (\'PT0890\',\'PT0854\',\'PT0856\',\'PT0857\') THEN \'New Inward\' WHEN \"Warehouse Name\" LIKE \'%TAURU%\' AND \"Putaway Code\" IN (\'PT17128\',\'PT17676\',\'PT18056\',\'PT18460\',\'PT18570\',\'PT18752\',\'PT18802\',\'PT19037\',\'PT19049\',\'PT19544\',\'PT19731\',\'PT20079\',\'PT20312\',\'PT20369\',\'PT20635\',\'PT20895\',\'PT20936\',\'PT21174\',\'PT21435\',\'PT21444\',\'PT21787\',\'PT21848\',\'PT22864\',\'PT22891\',\'PT22909\',\'PT22929\',\'PT23008\',\'PT23040\',\'PT23181\',\'PT23239\',\'PT23345\',\'PT23374\',\'PT23536\',\'PT23663\',\'PT23676\',\'PT23832\',\'PT23837\',\'PT23844\',\'PT23945\',\'PT23952\',\'PT23958\',\'PT23964\',\'PT24053\',\'PT24054\',\'PT24082\',\'PT24094\',\'PT24155\',\'PT24166\',\'PT24172\',\'PT24206\',\'PT24260\',\'PT24309\',\'PT24335\',\'PT24505\',\'PT24541\',\'PT24574\') THEN \'Store Return Inward\' WHEN \"Warehouse Name\" LIKE \'%TAURU%\' AND \"Putaway Code\" IN (\'PT0004\',\'PT0936\',\'PT0943\',\'PT0942\',\'PT0977\',\'PT0941\',\'PT0928\',\'PT0981\',\'PT0840\',\'PT0978\',\'PT0917\',\'PT0999\',\'PT0997\',\'PT0765\',\'PT0986\',\'PT6017\') THEN \'WH_Transfer_Inward\' WHEN \"Warehouse Name\" LIKE \'%TAURU%\' AND LOWER(a.\"Created By\") LIKE \'%northemp.050%\' THEN \'WH_Transfer_Inward\' WHEN \"Warehouse Name\" LIKE \'%TAURU%\' AND LOWER(a.type) LIKE \'%grn%\' AND a.created::DATE IN (\'2025-09-18\',\'2025-09-19\',\'2025-09-20\',\'2025-09-21\',\'2025-09-22\') THEN \'WH_Transfer_Inward\' WHEN \"Warehouse Name\" LIKE \'%TAURU%\' AND LOWER(a.\"Created By\") LIKE \'%northemp.049%\' THEN \'Store Return Inward\' WHEN \"Warehouse Name\" LIKE \'%WH1%\' AND LOWER(a.\"Created By\") LIKE \'%emp101%\' AND created >= \'2026-04-01\' THEN \'B2B MP Returns\' WHEN \"Warehouse Name\" LIKE \'%WH2%\' AND LOWER(a.\"Created By\") LIKE \'%emp101%\' AND created >= \'2026-04-01\' THEN \'B2B MP Returns\' WHEN \"Warehouse Name\" LIKE \'%NORTH%\' AND LOWER(a.\"Created By\") LIKE \'%emp102%\' AND created >= \'2026-04-01\' THEN \'B2B MP Returns\' WHEN \"Warehouse Name\" LIKE \'%WH1%\' AND LOWER(a.type) LIKE \'%grn%\' AND created >= \'2025-04-01\' THEN \'Store Return Inward\' WHEN \"Warehouse Name\" LIKE \'%WH1%\' AND LOWER(a.\"Created By\") LIKE \'%gopal%\' THEN \'Store Return Inward\' WHEN LOWER(a.\"Created By\") LIKE \'%store%\' THEN \'Store Return Inward\' WHEN LOWER(a.\"Created By\") LIKE \'%return%\' AND LOWER(a.type) LIKE \'%grn%\' THEN \'WPR Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' AND (LOWER(a.\"Created By\") LIKE \'%hemant%\' OR LOWER(a.\"Created By\") LIKE \'%adava%\' OR LOWER(a.\"Created By\") LIKE \'%guramm%\' OR LOWER(a.\"Created By\") LIKE \'%divya%\') THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%reverse%\' OR LOWER(a.type) LIKE \'%return%\' THEN \'B2C Return Inward\' WHEN LOWER(a.type) LIKE \'%cancelled%\' OR LOWER(a.type) LIKE \'%picklist%\' THEN \'Putback Activity\' WHEN LOWER(a.type) LIKE \'%shelf%\' THEN \'Audit Activity\' WHEN LOWER(a.type) LIKE \'%gatepass%\' THEN \'Gatepass Activity\' ELSE \'BAU_PT\' END AS final_type, a.type AS putaway_type, a.created::TIMESTAMP AS putaway_created, a.updated::TIMESTAMP AS putaway_updated, a.updated::DATE AS putaway_completed_date, a.\"Inventory Type\", CAST(a.\"Total Quantity\" AS NUMERIC) AS total_quantity, CAST(a.\"Putaway Completed Quantity\" AS NUMERIC) AS putaway_completed_quantity, CAST(a.\"Total Quantity\" - a.\"Putaway Completed Quantity\" AS NUMERIC) AS pending_qty, a.\"Putaway Status Code\", UPPER(a.\"Putaway Item Status Code\") AS \"Putaway Item Status Code\", a.\"Bad inventory Reason\", a.\"Warehouse Name\", a.\"Putaway Item Id\", a.\"Item Type skuCode\", a.\"Putaway qc Comment\", a.\"Created By\", a.\"Shelf Code\", c.skugroup, c.\"SKU_CLASS\" AS class, a.Category, CASE WHEN UPPER(TRIM(a.Category)) IN (\'NON- TRADING\',\'CARRY BAG\') THEN FALSE ELSE TRUE END AS is_trading, CASE WHEN UPPER(TRIM(a.Category)) = \'NON- TRADING\' THEN \'NON-TRADING\' WHEN UPPER(TRIM(a.Category)) = \'CARRY BAG\' THEN \'PACKAGING\' ELSE \'TRADING\' END AS category_group, a.NAME AS product_name, a.\"Batch Code\" FROM snitch_db.maplemonk.snitch_final_get_put_away_new AS a LEFT JOIN snitch_db.maplemonk.uc_final_item_master AS c ON a.\"Item Type skuCode\" = c.sku WHERE a.updated::DATE >= \'2024-04-01\' ) SELECT * FROM data WHERE CONCAT(\"Putaway Code\", \"Warehouse Name\") != \'PT18711SAPL-WH1\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_floor_pendency1 AS SELECT \"WAREHOUSE\", status AS reason, \"SAPL-WH1\" AS inward_type, \"SAPL-WH2\" AS source, store_returns::INTEGER AS quantity, SAPL_EMIZA AS remark, \"SAPL-SR\" AS dummy_1, TO_DATE(\"TOTAL\",\'DD/MM/YYYY\') AS ageing_date FROM SNITCH_DB.MAPLEMONK.GS_FLOOR_PENDENCY; CREATE OR REPLACE TABLE snitch_db.maplemonk.rts_summary_wh AS WITH rts AS ( SELECT TRY_TO_DATE(entry_date, \'DD/MM/YYYY\') AS date, sku AS style, description, repeat, new_style, CAST(REPLACE(online_qty, \',\', \'\') AS INT) AS online_qty, vendor, rts_status, TRY_TO_DATE(expected_delivery_date, \'DD/MM/YYYY\') AS expected_delivery_date, warehouse, class, ars, remark, photoshoot_received, qc_status, qc_report, costing, logic_po, pl_and_cm_receving_date, fabric_dc, work_order, mini_marker, invoice FROM snitch_db.maplemonk.gs_onlinegoods_rts ) SELECT rts.*, am.category, am.name AS product_name, am.sku_class, md.final_status, CASE WHEN logic_po IS NULL AND (LOWER(photoshoot_received) NOT IN (\'yes\') OR photoshoot_received IS NULL) THEN \'Shoot + PO Pending\' WHEN logic_po IS NULL THEN \'PO Pending\' WHEN LOWER(photoshoot_received) NOT IN (\'yes\') OR photoshoot_received IS NULL THEN \'Shoot Pending\' ELSE NULL END AS RCA, CASE WHEN rts.style LIKE \'%MP%\' THEN \'MARKETPLACE\' WHEN repeat = \'YES\' THEN \'REPEAT\' WHEN md.final_status = \'INWARD_NOT_DONE\' THEN \'CATALOGUED\' WHEN rts.style LIKE \'%4MLX%\' THEN \'LUXE\' WHEN LOWER(description) LIKE \'%trouse%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%short%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%deni%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%py%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%jogg%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%chino%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%track%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%pant%\' THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%cargo%\' THEN \'BOTTOMS\' WHEN LOWER(description) IN (\'trousers\',\'short\',\'boxer\',\'denim\',\'pyjama\',\'\') THEN \'BOTTOMS\' WHEN LOWER(description) LIKE \'%jac%\' THEN \'WINTER\' WHEN LOWER(description) LIKE \'%sweat%\' THEN \'WINTER\' END AS PRIORITY FROM rts LEFT JOIN snitch_db.maplemonk.uc_final_item_master am ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN am.skugroup) > 0 AND LEFT(am.skugroup, 2) = \'SH\' THEN UPPER(SPLIT_PART(am.skugroup, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN am.skugroup) > 0 THEN UPPER(SPLIT_PART(am.skugroup, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(am.skugroup, \'-\', 2)) || \'%\' ELSE UPPER(am.skugroup) || \'%\' END LEFT JOIN snitch_db.maplemonk.sku_group_sample_to_live md ON UPPER(rts.style) LIKE CASE WHEN POSITION(\'-\' IN md.sku_group) > 0 AND LEFT(md.sku_group, 2) = \'SH\' THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'%\' WHEN POSITION(\'-\' IN md.sku_group) > 0 THEN UPPER(SPLIT_PART(md.sku_group, \'-\', 1)) || \'-\' || UPPER(SPLIT_PART(md.sku_group, \'-\', 2)) || \'%\' ELSE UPPER(md.sku_group) || \'%\' END WHERE md.final_status NOT IN (\'NO_ISSUES\',\'others\'); CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.LOW_QTY_BINS AS WITH data AS ( SELECT facility, \"Shelf Code\" AS SHELF_CODE, zone, \"Section Code\" AS SECTION_CODE, BIN_CATEGORY, ROW_NAME, RACK_NAME, SHELF_NAME, BIN_NAME, SUM(total_qty) AS TOTAL_QTY FROM snitch_db.maplemonk.inventory_bin_analysis WHERE \"Section Code\" NOT IN (\'DEF\') AND LOWER(\"Shelf Code\") NOT LIKE \'%half%\' AND \"Shelf Code\" NOT LIKE \'%R1-%\' AND \"Shelf Code\" NOT LIKE \'%R2-%\' AND \"Shelf Code\" NOT LIKE \'%R3-%\' AND \"Shelf Code\" NOT LIKE \'%R4%\' AND \"Shelf Code\" NOT LIKE \'%R5%\' AND \"Shelf Code\" NOT LIKE \'%R6%\' AND \"Shelf Code\" NOT LIKE \'%R7%\' AND \"Shelf Code\" NOT LIKE \'%R8%\' AND \"Shelf Code\" NOT LIKE \'%R9%\' GROUP BY 1,2,3,4,5,6,7,8,9 ), analysis AS ( SELECT *, CASE WHEN TOTAL_QTY IS NULL OR total_qty = 0 THEN \'0\' WHEN TOTAL_QTY = 1 THEN \'1\' WHEN TOTAL_QTY = 2 THEN \'2\' WHEN TOTAL_QTY = 3 THEN \'3\' WHEN TOTAL_QTY = 4 THEN \'4\' WHEN TOTAL_QTY = 5 THEN \'5\' WHEN TOTAL_QTY >= 6 AND TOTAL_QTY < 11 THEN \'6-10\' WHEN TOTAL_QTY >= 11 AND TOTAL_QTY <= 15 THEN \'11-15\' WHEN TOTAL_QTY >= 16 AND TOTAL_QTY <= 20 THEN \'16-20\' WHEN TOTAL_QTY >= 21 AND TOTAL_QTY <= 25 THEN \'21-25\' WHEN TOTAL_QTY >= 26 AND TOTAL_QTY <= 50 THEN \'26-50\' WHEN TOTAL_QTY >= 51 THEN \'51+\' ELSE NULL END AS BRACKET FROM data ) SELECT * FROM analysis;",
                    "transaction": true
